"""JSON Schema (draft 2020-12) for FridgeChef. build.py writes it to ../schemas.json and validates examples.json."""
S = "string"; I = "integer"; N = "number"; B = "boolean"
def obj(props, req=None, extra=False):
    return {"type": "object", "properties": props, "required": req if req is not None else list(props), "additionalProperties": extra}
def arr(items, **kw):
    d = {"type": "array", "items": items}; d.update(kw); return d
def ref(n): return {"$ref": f"#/$defs/{n}"}

DEFS = {
    "DateLocal": {"type": S, "pattern": r"^\d{4}-\d{2}-\d{2}$"},
    "HexColor": {"type": S, "pattern": "^#[0-9A-Fa-f]{6}$"},
    "IngredientKey": {"type": S, "enum": ["egg","pork_minced","chicken","sausage","egg_tofu","holy_basil","spring_onion","chili","garlic","lime","tomato","carrot","cabbage","onion","cooked_rice","glass_noodle","milk"]},
    "Category": {"type": S, "enum": ["protein","herb","veg","carb","dairy"]},
    "ExpiryStatus": {"type": S, "enum": ["today","soon","ok","check"], "description": "today ≤1d red · soon 2–3d yellow · ok ≥4d green · check <0 grey (not recommended)"},
    "DietFilter": {"type": S, "enum": ["not_spicy","no_pork","vegetarian"]},
    "RecipeTag": {"type": S, "enum": ["spicy","pork","not_spicy","vegetarian","microwave_ok","kid_friendly"]},
    "Store": {"type": S, "enum": ["7-Eleven","ตลาด","Lotus's"]},
    "Detection": obj({"key": ref("IngredientKey"), "qty": {"type": N, "minimum": 0}, "added_on": ref("DateLocal"),
                      "confidence": {"type": N, "minimum": 0, "maximum": 1},
                      "bbox": arr({"type": N, "minimum": 0, "maximum": 1}, minItems=4, maxItems=4, description="x1,y1,x2,y2 normalized")},
                     ["key","qty","added_on","confidence"]),
    "CatalogItem": obj({"key": ref("IngredientKey"), "name_th": {"type": S}, "emoji": {"type": S}, "category": ref("Category"),
                        "shelf_life_days": {"type": I, "minimum": 1}, "unit_th": {"type": S}, "price_thb": {"type": I, "minimum": 0}, "store": ref("Store")}),
    "InventoryItem": obj({"key": ref("IngredientKey"), "name_th": {"type": S}, "emoji": {"type": S}, "category": ref("Category"),
                          "qty": {"type": N}, "unit_th": {"type": S}, "added_on": ref("DateLocal"), "shelf_life_days": {"type": I},
                          "days_left": {"type": I}, "status": ref("ExpiryStatus"), "confidence": {"type": N, "minimum": 0, "maximum": 1},
                          "confirmed": {"type": B}, "price_thb": {"type": I}}),
    "RecipeStep": obj({"n": {"type": I, "minimum": 1}, "text_th": {"type": S}, "timer_s": {"type": I, "minimum": 0}}),
    "Recipe": obj({"id": {"type": S, "pattern": "^[a-z0-9_]+$"}, "name_th": {"type": S}, "emoji": {"type": S}, "time_min": {"type": I, "minimum": 1},
                   "tags": arr(ref("RecipeTag")), "required": arr(ref("IngredientKey"), minItems=1), "optional": arr(ref("IngredientKey")),
                   "steps": arr(arr({"type": ["string","integer"]}, minItems=2, maxItems=2), minItems=1)}),
    "MenuFilters": obj({"max_missing": {"type": I, "minimum": 0, "maximum": 3}, "time_max": {"type": ["integer","null"]}, "diet": arr(ref("DietFilter"))}, []),
    "MenuMatch": obj({"recipe_id": {"type": S}, "name_th": {"type": S}, "emoji": {"type": S}, "time_min": {"type": I}, "tags": arr(ref("RecipeTag")),
                      "match_pct": {"type": I, "minimum": 0, "maximum": 100}, "uses": arr(ref("IngredientKey")),
                      "missing_required": arr(ref("IngredientKey")), "missing_optional": arr(ref("IngredientKey")),
                      "rescues": arr(ref("IngredientKey")), "rescue_value_thb": {"type": I, "minimum": 0},
                      "score": {"type": I}, "badge_th": {"type": S}}),
    "CookMode": obj({"recipe_id": {"type": S}, "name_th": {"type": S}, "steps": arr(ref("RecipeStep"), minItems=1),
                     "total_timer_s": {"type": I}, "timer_steps": {"type": I}}),
    "CookProgress": obj({"recipe_id": {"type": S}, "step_n": {"type": I}, "of": {"type": I}, "remaining_s": {"type": I, "minimum": 0},
                         "timer_done": {"type": B}, "next_hint_th": {"type": S}}),
    "Radar": obj({"groups": obj({k: arr(ref("IngredientKey")) for k in ["today","soon","ok","check"]}),
                  "at_risk_count": {"type": I}, "at_risk_value_thb": {"type": I}, "headline_th": {"type": S}}),
    "ShoppingItem": obj({"key": ref("IngredientKey"), "name_th": {"type": S}, "emoji": {"type": S}, "price_thb": {"type": I}}),
    "ShoppingStore": obj({"store": ref("Store"), "items": arr(ref("ShoppingItem"), minItems=1), "subtotal_thb": {"type": I}}),
    "ShoppingList": obj({"stores": arr(ref("ShoppingStore")), "total_thb": {"type": I}, "line_text": {"type": S}}),
    "DiceResult": obj({"seed": {"type": I}, "frames": arr({"type": S}, minItems=6, maxItems=6), "pick": {"type": S}}),
    "CookLogEntry": obj({"date": ref("DateLocal"), "recipe_id": {"type": S}, "rescued": arr(ref("IngredientKey")), "rescued_value_thb": {"type": I, "minimum": 0}}),
    "Wrapped": obj({"month": {"type": S, "pattern": r"^\d{4}-\d{2}$"}, "meals_cooked": {"type": I}, "items_rescued": {"type": I},
                    "value_saved_thb": {"type": I}, "top_recipe_id": {"type": ["string","null"]}, "top_recipe_name_th": {"type": ["string","null"]},
                    "best_streak_days": {"type": I}, "headline_th": {"type": S}}),
    "ShareCard": obj({"kind": {"type": S, "enum": ["rescue","wrapped","menu"]}, "size": {"type": S, "enum": ["1080x1920","1080x1080"]},
                      "title_th": {"type": S}, "lines_th": arr({"type": S}, maxItems=5), "bg": ref("HexColor"), "accent": ref("HexColor"), "footer": {"type": S}}),
    "Settings": obj({"staples": arr({"type": S}), "diet": arr(ref("DietFilter")), "household": {"type": I, "minimum": 1, "maximum": 8},
                     "stove": {"type": S, "enum": ["gas","electric_1","microwave_only"]}, "ai_vision": {"type": B}}, []),
    "LocalStore": obj({"version": {"const": 1}, "inventory": arr(ref("InventoryItem")), "history": arr(ref("CookLogEntry")),
                       "shopping": ref("ShoppingList"), "settings": ref("Settings"), "last_scan_at": {"type": ["string","null"]}},
                      ["version","inventory","history","settings"]),
    "AiVisionRequest": obj({"image_base64": {"type": S}, "allowed_keys": arr(ref("IngredientKey")), "locale": {"const": "th-TH"}}),
    "AiVisionResponse": obj({"detections": arr(obj({"key": ref("IngredientKey"), "qty": {"type": N}, "confidence": {"type": N, "minimum": 0, "maximum": 1},
                                                    "bbox": arr({"type": N}, minItems=4, maxItems=4)}, ["key","qty","confidence"])),
                             "unknown_items_th": arr({"type": S})}),
    "AiRecipeRequest": obj({"have": arr(ref("IngredientKey")), "staples": arr({"type": S}), "diet": arr(ref("DietFilter")), "time_max": {"type": ["integer","null"]}}),
    "AiRecipeResponse": obj({"recipes": arr(ref("Recipe"), maxItems=3), "disclaimer_th": {"type": S}}),
    "TestVector": obj({"id": {"type": S}, "fn": {"type": S}, "input": {}, "expect": {}}),
    "AnalyticsEvent": obj({"name": {"type": S, "enum": ["scan_started","scan_done","chip_confirmed","chip_removed","menu_opened","cook_started","timer_done","cook_finished","list_shared","dice_spun","card_shared"]},
                           "props": {"type": "object"}}, ["name"]),
}

ROOT = {"$schema": "https://json-schema.org/draft/2020-12/schema", "$id": "https://ai-wanla-app.local/fridgechef/schemas.json",
        "title": "FridgeChef examples.json", "description": "Schema for the FridgeChef pack examples + runtime data.",
        "$defs": DEFS, "type": "object",
        "required": ["meta","colors","persona","catalog","recipes","demo_input","expect_locked","inventory","radar","menu_top3","menu_all",
                     "confirm_lime_rerun","filters_examples","cook_mode","cook_progress","shopping_list","dice","wrapped","share_cards",
                     "local_store_example","ai_examples","ui_copy_th","reel_script","test_vectors"],
        "additionalProperties": True}
